public readonly ref struct MetricsTimer<TMetrics>
    where TMetrics : IMetricSink
{
    private readonly long _start;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public MetricsTimer()
    {
        _start = Stopwatch.GetTimestamp();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public void Dispose()
    {
            long ticks = Stopwatch.GetElapsedTime(_start).Ticks;
            TMetrics.AddTicks(ticks);
    }
}
